        ["게임을 실행하지 못했습니다: {0}"] = ("Could not start the game: {0}", "无法启动游戏：{0}", "ゲームを起動できませんでした: {0}"),
        ["설정 저장 실패: {0}"] = ("Could not save the setting: {0}", "保存设置失败：{0}", "設定の保存に失敗しました: {0}"),
        ["바꾼 언어는 매니저를 다시 시작하면 적용됩니다. 지금 다시 시작할까요?"] = ("The new language applies when the manager restarts. Restart now?", "新语言将在重新启动管理器后生效。现在重新启动吗？", "変更した言語はマネージャーの再起動後に反映されます。今すぐ再起動しますか？"),
        ["새 버전 v{0} 있음"] = ("New version v{0} available", "有新版本 v{0}", "新しいバージョン v{0} があります"),
        ["설정을 저장하지 못했습니다: {0}"] = ("Could not save the settings: {0}", "无法保存设置：{0}", "設定を保存できませんでした: {0}"),
        ["새 게임 폴더로 매니저를 다시 시작할까요?"] = ("Restart the manager with the new game folder?", "要使用新的游戏文件夹重新启动管理器吗？", "新しいゲームフォルダーでマネージャーを再起動しますか？"),
        ["설치된 것"] = ("installed", "已安装", "インストール済み"),
        ["Mods Menu가 아직 설치되어 있지 않습니다. 모드 목록에서 Mods Menu를 설치해 주세요."] = ("Mods Menu is not installed yet. Install Mods Menu from the mod list.", "尚未安装 Mods Menu。请在模组列表中安装 Mods Menu。", "Mods Menu はまだインストールされていません。Mod 一覧から Mods Menu をインストールしてください。"),
