        ["Mods Menu도 설치되어 있습니다. 둘이 함께 있으면 하나만 동작하니 Mods Menu는 제거해 주세요."] = ("Mods Menu is installed too. With both, only one works, so remove Mods Menu.", "Mods Menu 也已安装。两者同时存在时只有一个生效，请移除 Mods Menu。", "Mods Menu もインストールされています。両方あると片方しか動作しないので、Mods Menu を削除してください。"),
        ["설치된 모드 확인 중..."] = ("Checking installed mods...", "正在检查已安装的模组...", "インストール済み Mod を確認中..."),
        ["앞으로 모드를 {0}에 맞춰 설치합니다. 다시 배치할 설치된 모드는 없습니다."] = ("Mods will be installed for {0} from now on. No installed mods need to be moved.", "今后模组将按 {0} 安装。没有需要重新放置的已安装模组。", "今後 Mod は {0} に合わせてインストールします。配置し直すインストール済み Mod はありません。"),
        ["스크립트 로더"] = ("Script loader", "脚本加载器", "スクリプトローダー"),
        ["앞으로 모드를 {0}에 맞춰 설치합니다.\n이미 설치된 다음 모드도 지금 다시 배치할까요?\n"] = ("Mods will be installed for {0} from now on.\nMove these installed mods now as well?\n", "今后模组将按 {0} 安装。\n现在也重新放置以下已安装的模组吗？\n", "今後 Mod は {0} に合わせてインストールします。\n次のインストール済み Mod も今すぐ配置し直しますか？\n"),
        ["\n\n고른 옵션과 뺀 파일은 그대로 씁니다."] = ("\n\nThe chosen options and left-out files stay as they are.", "\n\n已选的选项和排除的文件保持不变。", "\n\n選んだオプションと外したファイルはそのまま使います。"),
        ["다시 배치 중..."] = ("Moving...", "正在重新放置...", "配置し直し中..."),
        ["{0} 다시 배치 중..."] = ("Moving {0}...", "正在重新放置 {0}...", "{0} を配置し直し中..."),
        ["다시 배치하지 못한 모드:\n"] = ("Mods that could not be moved:\n", "未能重新放置的模组：\n", "配置し直せなかった Mod:\n"),
        ["설치된 모드 {0}개를 {1}에 맞춰 다시 배치했습니다."] = ("Moved {0} installed mod(s) for {1}.", "已按 {1} 重新放置 {0} 个已安装的模组。", "インストール済み Mod {0} 個を {1} に合わせて配置し直しました。"),
        ["설치한 압축 파일이 MOD 폴더에 없어 옵션을 바꿀 수 없습니다.\n{0}"] = ("The installed archive is not in the MOD folder, so the options cannot be changed.\n{0}", "已安装的压缩包不在 MOD 文件夹中，无法更改选项。\n{0}", "インストールした圧縮ファイルが MOD フォルダーにないため、オプションを変更できません。\n{0}"),
        ["옵션 변경"] = ("Change options", "更改选项", "オプション変更"),
        ["압축 파일 확인 중..."] = ("Checking the archive...", "正在检查压缩包...", "圧縮ファイルを確認中..."),
