        ["보관 폴더로 이동 {0}개 · 폴더 제거 {1}개"] = ("move to kept files {0} · remove folders {1}", "移到保留文件夹 {0} 个 · 移除文件夹 {1} 个", "保管フォルダーへ移動 {0} 個 · フォルダー削除 {1} 個"),
        [" · 다른 설치가 쓰는 폴더 유지 {0}개"] = (" · keep folders used by other installs {0}", " · 保留其他安装使用的文件夹 {0} 个", " · 他のインストールが使うフォルダーを保持 {0} 個"),
        ["설치 후 변경되었거나 새로 생긴 파일은 지우지 않고 보관 폴더로 옮깁니다. 모드 설정이나 직접 넣은 파일은 거기서 꺼낼 수 있습니다."] = ("Files changed or created after install are not deleted but moved to the kept files folder. Mod settings or files you added yourself can be taken from there.", "安装后被修改或新生成的文件不会删除，而是移到保留文件夹。模组设置或你自己放入的文件可以从那里取回。", "インストール後に変更された、または新しくできたファイルは削除せず保管フォルダーに移します。Mod の設定や自分で入れたファイルはそこから取り出せます。"),
        ["덮어썼던 파일이 설치 후 변경되었습니다. 게임 업데이트로 바뀐 파일이라면 원본 복원 뒤 Steam 파일 검사가 필요할 수 있습니다."] = ("Files that were overwritten have changed since install. If a game update changed them, a Steam file check may be needed after the originals are restored.", "被覆盖的文件在安装后发生了变化。如果是游戏更新导致的，恢复原文件后可能需要用 Steam 验证游戏文件。", "上書きしたファイルがインストール後に変更されています。ゲームのアップデートで変わったファイルなら、元に戻した後に Steam でファイルの整合性確認が必要になるかもしれません。"),
        ["{0} 작업이 중간에 중단되었습니다.\n지금 마저 정리할까요?\n\n정리하기 전에는 새 설치를 할 수 없습니다."] = ("{0} was interrupted.\nFinish cleaning it up now?\n\nNothing new can be installed until it is cleaned up.", "{0} 操作中途中断了。\n现在完成清理吗？\n\n清理完成前无法进行新的安装。", "{0} の作業が途中で中断されました。\n今すぐ片付けを完了しますか？\n\n片付けるまでは新しいインストールができません。"),
        ["정리 중..."] = ("Cleaning up...", "正在清理...", "片付け中..."),
        ["정리 완료"] = ("Cleanup done", "清理完成", "片付け完了"),
        ["순서 저장 실패: {0}"] = ("Could not save the order: {0}", "保存顺序失败：{0}", "順番を保存できませんでした: {0}"),
        ["보관 폴더가 비어 있습니다."] = ("The kept files folder is empty.", "保留文件夹是空的。", "保管フォルダーは空です。"),
        ["보관 폴더의 파일 {0}개({1:0.#} MB, 제거 {2}번 분량)를 휴지통으로 보낼까요?\n\n"] = ("Send {0} file(s) in the kept files folder ({1:0.#} MB, from {2} removal(s)) to the Recycle Bin?\n\n", "要把保留文件夹中的 {0} 个文件（{1:0.#} MB，{2} 次移除的量）移到回收站吗？\n\n", "保管フォルダーのファイル {0} 個（{1:0.#} MB、削除 {2} 回分）をごみ箱に送りますか？\n\n"),
        ["모드를 제거할 때 지우지 않고 옮겨 둔 파일들입니다. 모드 설정 파일이나 설치 후 바뀐 파일일 수 있으니, 필요한 것이 있으면 먼저 [보관 폴더 열기]로 확인해 주세요."] = ("These are files moved aside instead of deleted when mods were removed. They may be mod settings or files changed after install, so check with [Open kept files] first if you need any.", "这些是移除模组时没有删除而移到这里的文件。可能是模组设置文件或安装后修改过的文件，如有需要请先用 [打开保留文件夹] 查看。", "Mod を削除したときに消さずに移しておいたファイルです。Mod の設定ファイルやインストール後に変わったファイルかもしれないので、必要なものがあれば先に [保管フォルダーを開く] で確認してください。"),
        ["보관 폴더 비우기"] = ("Empty kept files", "清空保留文件夹", "保管フォルダーを空にする"),
        ["보관 폴더 비우는 중..."] = ("Emptying the kept files folder...", "正在清空保留文件夹...", "保管フォルダーを空にしています..."),
        ["휴지통으로 보내지 못한 것:\n"] = ("Could not send to the Recycle Bin:\n", "未能移到回收站的项目：\n", "ごみ箱に送れなかったもの:\n"),
        ["보관 폴더를 비웠습니다 ({0:0.#} MB, 휴지통에서 되살릴 수 있음)."] = ("Emptied the kept files folder ({0:0.#} MB, can be restored from the Recycle Bin).", "已清空保留文件夹（{0:0.#} MB，可从回收站恢复）。", "保管フォルダーを空にしました（{0:0.#} MB、ごみ箱から復元できます）。"),
        ["구분선 추가"] = ("Add separator", "添加分隔线", "区切り線を追加"),
        ["구분선에 쓸 이름 (예: 그래픽, UI, 편의 기능)"] = ("Name for the separator (e.g. Graphics, UI, Quality of life)", "分隔线名称（例如：画面、UI、便利功能）", "区切り線の名前（例: グラフィック、UI、便利機能）"),
        ["구분선"] = ("Separator", "分隔线", "区切り線"),
        ["구분선 저장 실패: {0}"] = ("Could not save the separator: {0}", "保存分隔线失败：{0}", "区切り線を保存できませんでした: {0}"),
        ["구분선 이름 바꾸기"] = ("Rename separator", "重命名分隔线", "区切り線の名前を変更"),
        ["구분선 이름"] = ("Separator name", "分隔线名称", "区切り線の名前"),
        ["불러오는 중..."] = ("Loading...", "正在加载...", "読み込み中..."),
