        ["업데이트 가능"] = ("Update available", "可更新", "アップデートあり"),
        ["설치됨"] = ("Installed", "已安装", "インストール済み"),
        ["{0}에 {1} 있음 · {2}"] = ("{1} on {0} · {2}", "{0} 有 {1} · {2}", "{0} に {1} あり · {2}"),
        ["파일 없음"] = ("File missing", "文件丢失", "ファイルなし"),
        ["일부 파일 없음"] = ("Some files missing", "部分文件丢失", "一部ファイルなし"),
